    const confirm = page.getByRole('dialog', { name: `Load ${custom.name}?`, exact: true });
    await expect(confirm).toBeVisible();
    await viewer.screenshot({
      path: `test-results/${native ? 'native' : 'mock'}-tank-viewer-confirm.png`,
    });
    await confirm.getByRole('button', { name: 'No', exact: true }).click();
    await expect(confirm).toHaveCount(0);
    await page.getByRole('button', { name: `Load ${custom.name}`, exact: true }).click();
    await confirm.getByRole('button', { name: 'Yes', exact: true }).click();
    await expect(viewer).toHaveCount(0);
    expect((await snapshot(page)).parts).toEqual(enemy.parts);
    await page.getByRole('button', { name: 'Load a Tank...', exact: true }).click();
    await expect(viewer).toHaveAttribute('data-viewer-ready', 'true');
    await page.getByRole('button', { name: 'Search for tanks online', exact: true }).click();
    const message = page.getByRole('dialog', { name: 'Tank viewer message', exact: true });
    await expect(message).toContainText('Community tank search is not connected.');
    await message.getByRole('button', { name: 'Dismiss message', exact: true }).click();
    await page.getByRole('button', { name: 'Return to Tank Creator', exact: true }).click();
    expect((await snapshot(page)).parts).toHaveLength(0);
    expect(errors).toEqual([]);
    expect(outbound).toEqual([]);
  });
  await map.click();
  await expect(page.locator('#map-description')).toContainText('Map: Hidden');
  await map.press('Enter');
  await expect(page.locator('#map-description')).toContainText('Map: Compact');
});

test('original SWF music resumes and player volleys play extracted audio', async ({ page }) => {
  const swf =
    process.env.BT3_SWF_FILE ?? resolve('../documented-bubble-tank-3/re/bt3/uncompressed.swf');
  test.skip(!existsSync(swf), 'A local research SWF is required.');
  await watchAudio(page);
  await page.goto('/');
  await page.getByLabel('Bubble Tanks 3 Flash file').setInputFiles(swf);
  await play(page);
  await expect.poll(() => musicPlaying(page)).toBe(true);
  await page.keyboard.press('KeyP');
  await page.evaluate(() =>
    (window as unknown as { __testAudio: HTMLAudioElement[] }).__testAudio
      .filter((audio) => audio.loop)
      .at(-1)!
      .pause(),
  );
  await page.getByRole('button', { name: 'PLAY', exact: true }).click();
  await expect.poll(() => musicPlaying(page)).toBe(true);
  await expect(page.getByRole('dialog')).toHaveCount(0);
  const bounds = await page.locator('.game-canvas').boundingBox();
  await page.mouse.move(bounds!.x + bounds!.width * 0.8, bounds!.y + bounds!.height * 0.5);
  await page.mouse.down();
  await expect
    .poll(() =>
      page.evaluate(() =>
        (window as unknown as { __testAudio: HTMLAudioElement[] }).__testAudio.some(
          (audio) => !audio.loop && audio.duration > 0 && !audio.error,
        ),
      ),
    )
    .toBe(true);
